create table if not exists public.equipment_service_events(id uuid primary key default gen_random_uuid(),equipment_id uuid not null references public.customer_equipment(id) on delete cascade,job_id uuid not null references public.jobs(id) on delete cascade,technician_id uuid references public.users(id) on delete set null,service_type text not null default 'service',condition text,findings text,performed_work text,serviced_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(equipment_id,job_id)); create index if not exists idx_equipment_service_job on public.equipment_service_events(job_id); alter table public.equipment_service_events enable row level security; revoke all on public.equipment_service_events from anon; create policy equipment_service_read on public.equipment_service_events for select to authenticated using(public.has_permission_for_current_user('view_jobs') or public.has_permission_for_current_user('field_app')); create or replace function private.record_field_equipment_service(p_job_id uuid,p_equipment_id uuid,p_condition text,p_findings text,p_performed_work text) returns void language plpgsql security definer set search_path='' as $$ declare v_customer uuid; v_tech uuid; begin if not public.has_permission_for_current_user('field_app') then raise exception 'Field permission required'; end if; select customer_id,technician_id into v_customer,v_tech from public.jobs where id=p_job_id and status='on_site'; if v_customer is null then raise exception 'Job must be on site'; end if; if not exists(select 1 from public.customer_equipment where id=p_equipment_id and customer_id=v_customer and status='active') then raise exception 'Equipment does not belong to this customer'; end if; insert into public.equipment_service_events(equipment_id,job_id,technician_id,condition,findings,performed_work) values(p_equipment_id,p_job_id,v_tech,left(trim(p_condition),100),left(trim(p_findings),3000),left(trim(p_performed_work),3000)) on conflict(equipment_id,job_id) do update set condition=excluded.condition,findings=excluded.findings,performed_work=excluded.performed_work,serviced_at=now(); update public.customer_equipment set last_service_on=current_date,updated_at=now() where id=p_equipment_id; end $$; create or replace function public.record_field_equipment_service(p_job_id uuid,p_equipment_id uuid,p_condition text,p_findings text,p_performed_work text) returns void language sql set search_path='' as $$ select private.record_field_equipment_service(p_job_id,p_equipment_id,p_condition,p_findings,p_performed_work) $$; revoke all on function public.record_field_equipment_service(uuid,uuid,text,text,text) from public,anon; grant execute on function public.record_field_equipment_service(uuid,uuid,text,text,text) to authenticated;